from mitmproxy import http

def request(flow: http.HTTPFlow) -> None:
    if "{{match_host}}" in flow.request.pretty_host:
        flow.request.headers["x-injected"] = "{{inject_header}}"

def response(flow: http.HTTPFlow) -> None:
    if flow.response and flow.response.headers.get("content-type", "").startswith("text/html"):
        flow.response.text = flow.response.text.replace("</body>", "<!-- patched --></body>")
